function active(t){return !['closed','solved'].includes(t.status);}
function unanswered(t){return active(t)&&t.messages.filter(m=>['agent','client'].includes(m.type)).at(-1)?.type==='client';}
function overdue(t){return active(t)&&unanswered(t)&&t.due<Date.now();}
function clientTickets(){const isClient=currentUser&&currentUser.role==='client';const name=isClient?currentUser.name:'Azizbek Rahimov';return tickets.filter(t=>t.client===name||(isClient&&currentUser.id&&t.client_id===currentUser.id));}
function getTicket(id){return tickets.find(t=>t.id===Number(id));}
function currentTicket(){return getTicket(route.split('/').at(-1));}
function statusTag(t){return `<span class="tag ${t.status}"><i class="dot"></i>${statuses[t.status]}</span>`;}
function priorityTag(t){return `<span class="priority ${t.priority}">${icon('chart')}${priorities[t.priority]}</span>`;}
function duration(ms){const mins=Math.max(1,Math.ceil(Math.abs(ms)/60000));return mins>=60?`${Math.floor(mins/60)} s ${mins%60} daq`:`${mins} daq`;}
function fileSize(bytes){return bytes<1048576?`${Math.max(1,Math.ceil(bytes/1024))} KB`:`${(bytes/1048576).toFixed(1)} MB`;}
function sla(t){if(!active(t))return {text:t.status==='closed'?'Tasdiqlangan':'Tasdiq kutilmoqda',late:false};if(!unanswered(t))return {text:'Mijoz javobi kutilmoqda',late:false};return {text:overdue(t)?`Kechikkan · ${duration(t.due-Date.now())}`:`${duration(t.due-Date.now())} qoldi`,late:overdue(t)};}
function slaText(t){const s=sla(t);return `<span class="sla-text ${s.late?'late':''}">${icon(s.late?'alert':'clock')}${s.text}</span>`;}
function time(){return new Intl.DateTimeFormat('uz-UZ',{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Tashkent'}).format(new Date());}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(tickets));storageFailure=false;}catch{storageFailure=true;toast('Saqlash joyi yetarli emas. O‘zgarishlar shu seansda saqlanadi.');}}
function toast(text){if(storageFailure)text+=' · O‘zgarishlar faqat shu seansda saqlanadi.';clearTimeout(toastTimer);const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4000);}
function navLink(href,label,name,count){const selected=route===href||(href==='queue'&&(route.startsWith('ticket/')||route==='unanswered'));return `<a href="#${href}" class="${selected?'active':''}" ${selected?'aria-current="page"':''}>${icon(name)}${label}${count!==undefined?`<span class="nav-count">${count}</span>`:''}</a>`;}
async function apiFetch(path,options={}){if(typeof fetch!=='function')return {ok:false};const cfg=globalThis.YORDAM_CONFIG||{apiBase:''};const url=(cfg.apiBase||'')+path;const headers={'Content-Type':'application/json',...(options.headers||{})};if(authToken){headers['Authorization']=`Bearer ${authToken}`;headers['x-auth-token']=authToken;}try{const res=await fetch(url,{...options,headers});return await res.json();}catch(e){return {ok:false,error:e.message};}}
async function syncWithServer(){if(typeof fetch!=='function')return;try{if(authToken){const me=await apiFetch('/api/auth/me');if(me&&me.ok&&me.user){currentUser=me.user;try{localStorage.setItem('yordam_user',JSON.stringify(currentUser));}catch{}}}const res=await apiFetch('/api/tickets');if(res&&res.ok&&Array.isArray(res.tickets)&&res.tickets.length){tickets=res.tickets;persist();render();}}catch{}}
