function stats(){const open=tickets.filter(active).length,unread=tickets.filter(unanswered).length,late=tickets.filter(overdue).length,solved=tickets.filter(t=>['solved','closed'].includes(t.status)).length;return `<section class="stats" aria-label="Murojaatlar statistikasi">${[[open,'Ochiq murojaatlar','inbox','Jamoaning joriy navbati','green'],[unread,'Javob kutilmoqda','message','Mijozga javob berish kerak',''],[late,'Javob muddati kechikkan','clock','Birinchi navbatda ko‘rib chiqing',''],[solved,'Yechim berilgan','checkCircle','Tasdiqlangan va tasdiq kutilayotgan','']].map(([n,label,i,foot,c])=>`<div class="stat ${c}"><div class="between"><span class="stat-title">${label}</span><span class="stat-icon">${icon(i)}</span></div><div class="stat-number">${String(n).padStart(2,'0')}</div><div class="stat-foot ${c?'muted':''}">${icon(i==='clock'?'alert':'arrow')}<span class="${i==='clock'?'risk':''}">${foot}</span></div></div>`).join('')}</section>`;}
function filteredTickets(){let list=tickets.filter(t=>filter==='all'?t.status!=='closed':filter==='mine'?active(t)&&(t.assignee===(currentUser?.name||agents[0])||currentUser?.role==='admin'):filter==='unanswered'?unanswered(t):filter==='overdue'?overdue(t):t.status==='closed');if(search)list=list.filter(t=>`${t.id} ${t.title} ${t.client} ${t.assignee}`.toLocaleLowerCase().includes(search.toLocaleLowerCase()));return list.sort((a,b)=>sort==='deadline'?a.due-b.due:sort==='newest'?b.id-a.id:(Number(overdue(b))-Number(overdue(a)))||({urgent:0,high:1,normal:2,low:3}[a.priority]-{urgent:0,high:1,normal:2,low:3}[b.priority]));}
function sortLabel(){return sort==='deadline'?'javob muddati':sort==='newest'?'eng yangi':'kechikkanlar, so‘ng ustuvorlik';}
function queueFilters(){return `<div class="tabs" role="group" aria-label="Navbat filtrlari">${[['all','Yopilmagan',tickets.filter(t=>t.status!=='closed').length],['mine','Meniki',tickets.filter(t=>active(t)&&t.assignee===agents[0]).length],['unanswered','Javobsiz',tickets.filter(unanswered).length],['overdue','Kechikkan',tickets.filter(overdue).length],...(route==='dashboard'?[]:[['closed','Yopilgan',tickets.filter(t=>t.status==='closed').length]])].map(([key,label,count])=>`<button class="filter ${filter===key?'active':''}" data-action="filter" data-value="${key}" aria-pressed="${filter===key}">${label}<b>${count}</b></button>`).join('')}</div>`;}
function tableRows(compact=false){const list=filteredTickets(),visible=compact?list.slice(0,5):list;return visible.map(t=>`<tr><td class="ticket-subject"><a href="#ticket/${t.id}">${esc(t.title)}</a><span class="small">${unanswered(t)?'<i class="unread"></i>':''}#HD-${t.id} &nbsp;·&nbsp; ${esc(t.category)}</span></td><td class="client-column"><div class="flex table-client">${avatar(t.client,t.color)}<span class="name">${esc(t.client)}</span></div></td><td>${statusTag(t)}</td><td>${priorityTag(t)}</td><td class="assignee-column"><span class="flex" style="gap:6px">${avatar(t.assignee,'mint','small-avatar')}<span class="small">${esc(t.assignee.split(' ')[0])}</span></span></td><td>${slaText(t)}</td></tr>`).join('')||`<tr><td colspan="6"><div class="empty">${icon('search')}<h3>Murojaatlar topilmadi</h3><p>Qidiruvni o‘zgartiring yoki boshqa filtrni tanlang.</p><button class="btn" data-action="clear-search">Filtrlarni tozalash</button></div></td></tr>`;}
function queuePanel(compact=false){return `<section class="panel ${compact?'compact-table':''}"><div class="panel-head"><div><h2>${'Murojaatlar navbati'}</h2><p>${compact?'E’tiboringizni kutayotgan murojaatlar':'Mijozlarning so‘rovlari va javob muddati'}</p></div>${compact?`<a class="text-link" href="#queue">Barchasini ko‘rish ${icon('arrow')}</a>`:`<label class="flex small muted">Tartib: <select id="queue-sort" aria-label="Navbatni tartiblash" style="border:1px solid var(--line);padding:8px;border-radius:6px;background:white"><option value="priority" ${sort==='priority'?'selected':''}>Kechikkanlar va ustuvorlik</option><option value="deadline" ${sort==='deadline'?'selected':''}>Javob muddati</option><option value="newest" ${sort==='newest'?'selected':''}>Eng yangi</option></select></label>`}</div><div class="queue-toolbar"><div id="queue-filters">${queueFilters()}</div><label class="search-field">${icon('search')}<input id="queue-search" type="search" aria-label="Murojaatlarni qidirish" placeholder="Murojaatni qidirish…" value="${esc(search)}"></label></div>${filter==='unanswered'?'<div class="queue-status-bar">Faqat mijozning oxirgi xabariga ommaviy javob berilmagan murojaatlar. Ichki izoh javob hisoblanmaydi.</div>':''}<div class="table-scroll"><table class="ticket-table"><thead><tr><th scope="col">Murojaat</th><th scope="col" class="client-column">Mijoz</th><th scope="col">Holat</th><th scope="col">Ustuvorlik</th><th scope="col" class="assignee-column">Mas’ul</th><th scope="col">Javob muddati</th></tr></thead><tbody id="queue-rows">${tableRows(compact)}</tbody></table></div><div class="table-bottom"><span id="queue-count" role="status" aria-live="polite">${compact?Math.min(filteredTickets().length,5):filteredTickets().length} ta ko‘rsatilmoqda · ${filteredTickets().length} ta murojaat</span><span id="queue-sort-label">${icon('shield')} Tartib: ${sortLabel()}</span></div></section>`;}
function slaPanel(){const total=tickets.filter(active).length,late=tickets.filter(overdue).length,rate=total?Math.round((total-late)/total*100):100;return `<section class="panel"><div class="panel-head"><h2>Javob muddati nazorati</h2>${icon('clock')}</div><div class="body-pad"><div class="sla-ring" style="background:conic-gradient(var(--green) 0deg ${rate*3.6}deg,#eaf0e4 ${rate*3.6}deg 360deg)" role="img" aria-label="${rate} foiz ochiq murojaatlarda javob muddati kechikmagan"><div class="sla-ring-content"><strong>${rate}%</strong><span>Muddat ichida</span></div></div><div class="legend"><span><i class="dot" style="color:var(--green)"></i>Muddat ichida</span><span><i class="dot" style="color:#c1cfb4"></i>Kechikkan</span></div><div class="hint-box">${icon('alert')}<span>${late} ta murojaatning javob muddati o‘tgan. <a href="#unanswered"><strong>Navbatni ko‘rib chiqing.</strong></a></span></div></div></section>`;}
function teamPanel(){return `<section class="panel"><div class="panel-head"><h2>Jamoa yuklamasi</h2><a href="#team" class="text-link">${icon('arrow')}<span class="small">Ko‘rish</span></a></div><div class="body-pad">${agents.map((name,i)=>{const n=tickets.filter(t=>active(t)&&t.assignee===name).length;return `<div class="team-member">${avatar(name,['mint','lilac','peach'][i])}<div class="grow"><strong>${name.split(' ')[0]} ${name.split(' ')[1][0]}.</strong><div class="team-progress"><span style="width:${Math.min(n/4*100,100)}%"></span></div></div><span class="member-count">${n} ta</span></div>`;}).join('')}</div></section>`;}
function activityPanel(){const entries=tickets.flatMap(t=>t.messages.filter(m=>m.type==='event').map(m=>({...m,ticket:t.id}))).slice(-3).reverse();return `<section class="panel"><div class="panel-head"><h2>So‘nggi faollik</h2><span class="small muted">Murojaatlar tarixi</span></div><div class="body-pad">${entries.map(m=>`<div class="activity-row"><span class="activity-icon">${icon('refresh')}</span><div><strong>${esc(m.text)}</strong><p><a href="#ticket/${m.ticket}">#HD-${m.ticket}</a></p></div><time>${esc(m.time)}</time></div>`).join('')}</div></section>`;}
function dashboard(){const firstName=currentUserName().split(' ')[0];return `${heading(`Xayrli kun, ${esc(firstName)}!`,'Jamoangizning bugungi ish holati. Muhim murojaatlar bir joyda.',`<a class="btn primary" href="#queue">${icon('inbox')}Navbatga o‘tish ${icon('arrow')}</a>`,'QO‘LLAB-QUVVATLASH MARKAZI')}${stats()}<div class="dashboard-grid">${queuePanel(true)}<div class="stack">${slaPanel()}${teamPanel()}</div></div><div class="bottom-grid"><section class="panel quick-card"><span class="large-icon">${icon('book')}</span><div><h2>Yaxshi javob bilimdan boshlanadi.</h2><p>Ko‘p uchraydigan savollar va aniq ko‘rsatmalar bilan mijozga tezroq yordam bering.</p></div><a href="#knowledge" class="btn">Bilimlar bazasi ${icon('arrow')}</a></section>${activityPanel()}</div>`;}
function queuePage(){return `${heading(filter==='unanswered'?'Javobsiz murojaatlar':'Murojaatlar','Navbatni saralang, javob muddatini kuzating va mijozga yordam bering.',`<a href="#reports" class="btn">${icon('chart')}Hisobotlarni ko‘rish</a>`)}${stats()}${queuePanel()}`;}
function messages(t,client=false){return `<div class="conversation-feed"><div class="date-line">Murojaat tarixi</div>${t.messages.filter(m=>!client||m.type!=='internal').map(m=>m.type==='event'?`<div class="event-line">${esc(m.text)} · ${esc(m.time)}</div>`:`<article class="message ${esc(m.type)}">${avatar(m.author||t.client,m.type==='client'?t.color:'mint')}<div class="message-body"><div class="message-meta"><strong>${esc(m.author||t.client)}</strong>${m.type==='agent'?'<span class="muted">· Agent</span>':''}<time>${esc(m.time)}</time></div><div class="bubble">${m.type==='internal'?`<div class="private-label">${icon('lock')}Ichki izoh · faqat jamoa uchun</div>`:''}${esc(m.text)}${(m.files||[]).map(f=>`<${f.id?'button type="button" data-file-id="'+esc(f.id)+'"':'div'} class="attachment">${icon('file')}<div><strong>${esc(f.name)}</strong><span>${fileSize(f.size)} · ${f.id?'Ko‘rish va yuklab olish':'Biriktirilgan fayl'}</span></div></${f.id?'button':'div'}>`).join('')}</div></div></article>`).join('')}</div>`;}
function composer(t){const priv=mode==='internal';return `<section class="composer" aria-label="Javob yozish"><div class="composer-tabs" role="tablist" aria-label="Xabar turi"><button class="composer-tab" id="public-tab" role="tab" aria-controls="composer-form" tabindex="${priv?-1:0}" aria-selected="${!priv}" data-action="mode" data-value="public">${icon('message')}Mijozga javob</button><button class="composer-tab private" id="internal-tab" role="tab" aria-controls="composer-form" tabindex="${priv?0:-1}" aria-selected="${priv}" data-action="mode" data-value="internal">${icon('lock')}Ichki izoh</button></div><form id="composer-form" role="tabpanel" aria-labelledby="${priv?'internal-tab':'public-tab'}"><div class="composer-box ${priv?'private':''}"><div class="composer-banner">${icon(priv?'lock':'users')}${priv?'Faqat jamoa ko‘radi. Bu izoh mijozga yuborilmaydi.':`Qabul qiluvchi: ${esc(t.client)} · Ommaviy javob`}</div><textarea id="composer-text" aria-label="${priv?'Ichki izoh matni':'Mijozga javob matni'}" placeholder="${priv?'Jamoa uchun ichki izoh yozing…':'Mijozga aniq va tushunarli javob yozing…'}" required maxlength="5000">${esc(drafts[t.id]?.[mode]||'')}</textarea><div class="composer-bottom"><span class="muted">${priv?'Ichki va ommaviy qoralamalar alohida saqlanadi.':'Yuborishdan oldin javobni ko‘rib chiqasiz.'}</span><button type="submit" class="btn ${priv?'amber':'primary'}">${icon(priv?'lock':'send')}${priv?'Ichki izohni saqlash':'Javobni ko‘rib chiqish'}</button></div></div></form></section>`;}
function detail(){const t=currentTicket();if(!t)return emptyPage();const s=sla(t);return `<div class="detail-heading"><a class="back-link" href="#queue">${icon('back')}Murojaatlar navbati</a><div class="between"><h1>${esc(t.title)}</h1>${statusTag(t)}</div><div class="flex small muted">#HD-${t.id}<span>·</span>${esc(t.client)}<span>·</span>${esc(t.created)}</div></div><div class="detail-grid"><section class="panel"><div class="conversation-head between"><h2>Yozishmalar</h2><span>${t.messages.filter(m=>m.type!=='event').length} ta xabar</span></div>${messages(t)}${t.status==='closed'?'<div class="composer"><div class="hint-box">Mijoz yechimni tasdiqlagan. Murojaat yopilgan.</div></div>':composer(t)}</section><aside class="stack"><section class="panel meta-panel"><h2>Murojaat tafsilotlari</h2><label class="field"><span>Holat</span><select id="ticket-status" ${!active(t)?'disabled':''}>${['new','progress','reopened'].map(k=>`<option value="${k}" ${t.status===k?'selected':''}>${statuses[k]}</option>`).join('')}${!active(t)?`<option value="${t.status}" selected>${statuses[t.status]}</option>`:''}</select></label><label class="field"><span>Ustuvorlik</span><select id="ticket-priority">${Object.entries(priorities).map(([k,v])=>`<option value="${k}" ${t.priority===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field"><span>Mas’ul agent</span><select id="ticket-assignee">${agents.map(a=>`<option ${t.assignee===a?'selected':''}>${a}</option>`).join('')}</select></label><div class="meta-item"><span>Toifa</span><strong>${esc(t.category)}</strong></div><hr class="separator">${active(t)?'<button class="btn primary metadata-submit" data-action="resolve">'+icon('checkCircle')+'Yechim taklif qilish</button>':`<div class="sla-banner">${statuses[t.status]}${t.status==='solved'?' · Mijoz tasdig‘i kutilmoqda':''}</div>`}<p class="safe-info">${icon('shield')}Murojaat mijoz yechimni tasdiqlagandan keyin yopiladi.</p></section><section class="panel meta-panel"><h2>Javob muddati</h2><div class="sla-banner ${s.late?'late':''}"><strong>${icon(s.late?'alert':'clock')}${s.text}</strong>${unanswered(t)?'Ommaviy javob yuborilguncha vaqt hisoblanadi.':'Ichki izohlar javob muddatini to‘xtatmaydi.'}</div><div class="meta-item"><span>Xizmat darajasi</span><strong>${priorities[t.priority]}</strong></div><div class="meta-item"><span>Javobsiz</span><strong>${unanswered(t)?'Ha · mijoz kutmoqda':'Yo‘q'}</strong></div></section><section class="panel meta-panel"><h2>Mijoz</h2><div class="flex">${avatar(t.client,t.color,'big')}<div><strong>${esc(t.client)}</strong><p class="small muted">${esc(t.company)}</p></div></div><div class="meta-item"><span>Murojaatlar</span><strong>${tickets.filter(x=>x.client===t.client).length} ta</strong></div><div class="meta-item"><span>Kanal</span><strong>Mijoz portali</strong></div></section></aside></div>`;}

function mobileCard(t){return `<a class="mobile-ticket" href="#client/ticket/${t.id}"><div class="between"><span class="id">#HD-${t.id}</span>${statusTag(t)}</div><h3>${esc(t.title)}</h3>${slaText(t)}<div class="ticket-bottom"><span>${esc(t.category)}</span><span>${esc(t.created)}</span></div></a>`;}
function clientHome(){const list=clientTickets().filter(t=>t.status!=='closed');const isClient=currentUser&&currentUser.role==='client';const clientName=isClient?currentUser.name:'Azizbek Rahimov';return `<p class="eyebrow" style="margin-bottom:7px">XAYRLI KUN, ${esc(clientName.toUpperCase())}</p><h1>Sizga yordam beramiz.</h1><p class="intro">Savollaringiz va yechimlar — bir joyda.</p><section class="welcome-card"><h2>Muammo yuzaga keldimi?</h2><p>Bizga yozing. Jamoamiz murojaatingizni ko‘rib chiqadi.</p><a class="btn" href="#client/create">${icon('plus')}Yangi murojaat</a></section><div class="mobile-section-title"><h2>Faol murojaatlar <span class="muted">(${list.length})</span></h2><a href="#client/list">Barchasi ${icon('arrow')}</a></div>${list.slice(0,2).map(mobileCard).join('')}<a class="faq-card" href="#client/knowledge">${icon('book')}<div><h3>Javobni tezroq toping</h3><p>Ko‘p beriladigan savollar</p></div>${icon('arrow')}</a>`;}
function clientList(){const list=clientTickets().filter(t=>clientTab==='closed'?t.status==='closed':t.status!=='closed');return `<h1>Mening murojaatlarim</h1><p class="intro">Har bir murojaatning holatini kuzating.</p><div class="tabs" role="group" aria-label="Mijoz murojaatlari">${[['active','Faol'],['closed','Yopilgan']].map(([key,label])=>`<button class="filter ${clientTab===key?'active':''}" data-action="client-tab" data-value="${key}" aria-pressed="${clientTab===key}">${label}<b>${clientTickets().filter(t=>key==='closed'?t.status==='closed':t.status!=='closed').length}</b></button>`).join('')}</div>${list.map(mobileCard).join('')||'<div class="empty">'+icon('inbox')+'<h3>Hozircha murojaat yo‘q</h3><p>Yordam kerak bo‘lsa, yangi murojaat yarating.</p></div>'}<a class="btn primary full-width" href="#client/create">${icon('plus')}Yangi murojaat</a>`;}
function clientCreate(){return `<a href="#client/home" class="back-link">${icon('back')}Bosh sahifa</a><h1>Yangi murojaat</h1><p class="intro">Muammoni yozing. Qolganini birga hal qilamiz.</p><form id="create-form"><label class="field"><span>Toifa</span><select id="create-category" name="category">${['To‘lovlar','Texnik muammo','Hisob','Hisobotlar','Boshqa'].map(c=>`<option ${createDraft.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label class="field"><span>Murojaat mavzusi <span class="muted">*</span></span><input id="create-title" name="title" placeholder="Masalan, balans to‘ldirilmadi" required minlength="5" maxlength="120" value="${esc(createDraft.title)}"></label><label class="field"><span>Batafsil tavsif <span class="muted">*</span></span><textarea id="create-description" name="description" required minlength="10" maxlength="5000" placeholder="Nima sodir bo‘ldi? Qanday yordam kerak?">${esc(createDraft.description)}</textarea><p class="field-help">Muammo sodir bo‘lgan vaqt va bajarilgan qadamlarni yozing.</p></label><div class="field"><span>Fayl biriktirish <span class="muted">· ixtiyoriy</span></span><label class="dropzone" for="create-files">${icon('upload')}Fayl yoki skrinshot tanlang<span>PNG, JPG yoki PDF · har biri 10 MB gacha</span></label><input id="create-files" type="file" accept="image/png,image/jpeg,application/pdf" multiple style="position:absolute;width:1px;height:1px;opacity:0" aria-label="Fayllarni biriktirish"><div id="file-list" class="file-list">${fileList()}</div><p id="file-error" class="error-message" role="alert"></p></div><div class="mobile-form-note">${icon('clock')}Javob muddati ustuvorlikka qarab belgilanadi. Holatni murojaat sahifasida kuzatasiz.</div><button class="btn primary full-width" type="submit">Murojaatni yuborish ${icon('arrow')}</button></form>`;}
function fileList(){return files.map((f,i)=>`<div class="between"><span>${esc(f.name)} · ${fileSize(f.size)}</span><button type="button" data-action="remove-file" data-value="${i}" aria-label="${esc(f.name)} faylini olib tashlash">×</button></div>`).join('');}
function clientDetail(){const t=currentTicket();const isClient=currentUser&&currentUser.role==='client';const allowedName=isClient?currentUser.name:'Azizbek Rahimov';if(!t||(t.client!==allowedName&&(!isClient||!t.client_id||t.client_id!==currentUser?.id)))return emptyPage();const s=sla(t);return `<a class="back-link" href="#client/list">${icon('back')}Murojaatlarim</a><div class="between"><span class="small muted">#HD-${t.id}</span>${statusTag(t)}</div><h1 class="mobile-detail-title">${esc(t.title)}</h1><div class="sla-banner ${s.late?'late':''}"><strong>${icon(s.late?'alert':'clock')}${s.text}</strong>${s.late?'Kechikish uchun uzr. Murojaatingiz jamoa e’tiborida.':t.status==='solved'?'Yechimni tekshirib, natijasini tasdiqlang.':t.status==='closed'?'Yechim tasdiqlandi. Muammo qolgan bo‘lsa, qayta oching.':'Agent javobi shu sahifada ko‘rinadi.'}</div>${messages(t,true)}${t.status==='solved'?`<div class="resolution-card"><h3>${icon('checkCircle')}Muammo hal bo‘ldimi?</h3><p>Taklif qilingan yechimni tekshiring. Muammo qolgan bo‘lsa, murojaatni qayta ochishingiz mumkin.</p><button class="btn primary full-width" data-action="confirm-resolution">${icon('check')}Ha, yechimni tasdiqlash</button><button class="btn full-width" data-action="reopen">${icon('refresh')}Yo‘q, qayta ochish</button></div>`:t.status==='closed'?`<button class="btn full-width" data-action="reopen">${icon('refresh')}Muammo qolgan · qayta ochish</button>`:`<form id="client-reply-form"><label class="field"><span>Agentga javob</span><textarea id="client-reply" placeholder="Qo‘shimcha ma’lumot yozing…" required maxlength="5000">${esc(drafts[t.id]?.client||'')}</textarea></label><button class="btn primary full-width" type="submit">${icon('send')}Javob yuborish</button></form>`}`;}
function createdPage(){const id=route.split('/')[2];const t=getTicket(id===undefined?lastCreated:id);const isClient=currentUser&&currentUser.role==='client';const allowedName=isClient?currentUser.name:'Azizbek Rahimov';if(!t||(t.client!==allowedName&&(!isClient||!t.client_id||t.client_id!==currentUser?.id)))return emptyPage();return `<div class="success-view"><div class="success-mark">${icon('check')}</div><h1>Murojaatingiz qabul qilindi!</h1><p>Jamoamiz muammoni ko‘rib chiqadi. Javob va yangiliklarni shu yerda kuzating.</p><div class="success-receipt"><div class="meta-item"><span>Murojaat raqami</span><strong>#HD-${t.id}</strong></div><div class="meta-item"><span>Holat</span>${statusTag(t)}</div><div class="meta-item"><span>Birinchi javob</span><strong>4 soat ichida</strong></div></div><a href="#client/ticket/${t.id}" class="btn primary full-width">Murojaatni ko‘rish ${icon('arrow')}</a><a href="#client/home" class="btn quiet full-width" style="margin-top:10px">Bosh sahifaga qaytish</a></div>`;}
const articles=[{title:'To‘lov balansda ko‘rinmasa nima qilish kerak?',category:'To‘lovlar',text:'To‘lov bajarilgan, lekin balans yangilanmagan bo‘lsa, to‘lov holatini tekshiring.',steps:['To‘lov ilovasida tranzaksiya muvaffaqiyatli bajarilganini tekshiring.','Shaxsiy kabinet sahifasini yangilang.','Muammo qolsa, yangi murojaatga to‘lov cheki va vaqtini biriktiring.']},{title:'Parolni qanday tiklash mumkin?',category:'Hisob',text:'Kirish sahifasida parolni tiklash orqali hisobingizga qayta kirishingiz mumkin.',steps:['Kirish sahifasida “Parolni unutdingizmi?” ni tanlang.','Hisobingizga bog‘langan telefon raqamini kiriting.','SMS kodni kiriting va yangi parolni saqlang. Kod kelmasa, yordam xizmatiga yozing.']},{title:'Hisobotni qanday yuklab olish mumkin?',category:'Hisobotlar',text:'Shaxsiy kabinetda hisobot davri va kerakli formatni tanlang.',steps:['Hisobotlar bo‘limini oching.','Boshlanish va tugash sanalarini belgilang.','Excel yoki CSV formatini tanlab, “Yuklab olish” ni bosing.']}];
function knowledge(client=false){return `${client?'<h1>Bilimlar bazasi</h1><p class="intro">Savolingizga javobni shu yerda toping.</p>':heading('Bilimlar bazasi','Ko‘p uchraydigan savollar uchun aniq ko‘rsatmalar.')}<label class="search-field" style="margin-bottom:22px">${icon('search')}<input id="article-search" type="search" aria-label="Maqolalarni qidirish" placeholder="Savol yoki kalit so‘z…" style="width:100%;min-height:44px"></label><div id="article-list">${articleCards(client)}</div>`;}
function articleCards(client=false,q=''){return articles.map((a,i)=>({...a,i})).filter(a=>`${a.title} ${a.category}`.toLocaleLowerCase().includes(q.toLocaleLowerCase())).map(a=>`<a class="faq-card" href="#${client?'client/':''}article/${a.i}">${icon('book')}<div><h3>${a.title}</h3><p>${a.category} · 2 daqiqalik o‘qish</p></div>${icon('arrow')}</a>`).join('')||'<div class="empty"><h3>Maqola topilmadi</h3><p>Boshqa so‘z bilan qidiring yoki murojaat yuboring.</p></div>';}
function article(){const a=articles[Number(route.split('/').at(-1))];if(!a)return emptyPage();const client=route.startsWith('client');return `<article class="article"><a class="back-link" href="#${client?'client/':''}knowledge">${icon('back')}Bilimlar bazasi</a><p class="eyebrow">${a.category}</p><h1 style="font-size:${client?22:29}px">${a.title}</h1><p>${a.text}</p><h2>Amallar ketma-ketligi</h2><ol>${a.steps.map(s=>`<li>${s}</li>`).join('')}</ol><div class="article-footer"><h3>Javob yordam bermadimi?</h3><p>Muammoni batafsil yozing. Jamoamiz sizga yordam beradi.</p><a class="btn primary" href="#client/create">${icon('plus')}Murojaat yaratish</a></div></article>`;}
