let googleClientId = '';
let googleAuthClientReady = false;

async function initGoogleAuth() {
  try {
    const res = await apiFetch('/api/auth/google/config');
    if (res && res.ok && res.configured && res.clientId) {
      googleClientId = res.clientId;
      setupGoogleIdentityServices();
    }
  } catch {}
}

function setupGoogleIdentityServices() {
  if (!googleClientId || typeof window === 'undefined') return;
  let attempts = 0;
  const checkGsi = () => {
    if (window.google && window.google.accounts && window.google.accounts.id) {
      try {
        window.google.accounts.id.initialize({
          client_id: googleClientId,
          callback: handleGoogleCredentialResponse,
          auto_select: false,
          cancel_on_tap_outside: true
        });
        googleAuthClientReady = true;
        renderGoogleSignInButton();
      } catch (e) {
        console.error('Google Auth init error:', e);
      }
    } else if (attempts < 25) {
      attempts++;
      setTimeout(checkGsi, 200);
    }
  };
  checkGsi();
}

function renderGoogleSignInButton() {
  const container = document.getElementById('g_id_signin_gate');
  if (!container || !window.google?.accounts?.id || !googleClientId) return;
  try {
    container.innerHTML = '';
    window.google.accounts.id.renderButton(container, {
      theme: 'outline',
      size: 'large',
      type: 'standard',
      text: 'continue_with',
      shape: 'rectangular',
      logo_alignment: 'left',
      width: 320
    });
    window.google.accounts.id.prompt();
  } catch {}
}

async function handleGoogleCredentialResponse(response) {
  if (!response || !response.credential) return;
  toast('Google hisobingiz tekshirilmoqda...');
  try {
    const res = await apiFetch('/api/auth/google/verify', {
      method: 'POST',
      body: JSON.stringify({ credential: response.credential })
    });
    if (res && res.ok && res.user) {
      currentUser = res.user;
      authToken = res.token;
      authGateError = '';
      try {
        localStorage.setItem('yordam_user', JSON.stringify(currentUser));
        localStorage.setItem('yordam_token', authToken);
      } catch {}
      closeDialog();
      if (currentUser.role === 'client') location.hash = 'client/home';
      else location.hash = 'dashboard';
      render();
      toast(`Xush kelibsiz, ${currentUser.name}! Google orqali kirdingiz.`);
      syncWithServer();
    } else {
      authGateError = res?.error || 'Google orqali kirishda xatolik yuz berdi.';
      render();
    }
  } catch (err) {
    authGateError = err.message;
    render();
  }
}

async function handleGoogleLoginClick(btn) {
  if (btn) {
    btn.classList.add('loading');
    btn.setAttribute('disabled', 'true');
    const origHtml = btn.innerHTML;
    btn.innerHTML = `<span class="oauth-spinner"></span> <span>Google ga ulanmoqda...</span>`;
    try {
      const res = await apiFetch('/api/auth/google/config');
      if (res && res.ok && res.configured && res.clientId) {
        window.location.href = '/api/auth/oauth/google';
        return;
      }
    } catch {}
    btn.classList.remove('loading');
    btn.removeAttribute('disabled');
    btn.innerHTML = origHtml;
  }
  showGoogleConfigGuideModal();
}

